import Foundation
import UIKit
import AVFoundation
import CoreImage
import OpenIMCore

/// AVCapture outputs deliver RAM samples. Photo JPEGs and H.264/AAC fragments
/// go straight into SQLCipher; no movie-file output or UIImagePicker movie URL.
@available(iOS 13.0, *)
final class PMCaptureController:UIViewController,AVCaptureVideoDataOutputSampleBufferDelegate,AVCaptureAudioDataOutputSampleBufferDelegate,AVCapturePhotoCaptureDelegate {
    var completion:((Result<Any,Error>)->Void)?
    private weak var authority:PMVaultAuthority?
    private let actor:PMVaultActor,kind:String,maxDuration:Double
    private let session=AVCaptureSession(),sessionQueue=DispatchQueue(label:"com.szputy.im.camera-session"),samples=DispatchQueue(label:"com.szputy.im.camera-samples")
    private let photo=AVCapturePhotoOutput(),video=AVCaptureVideoDataOutput(),audio=AVCaptureAudioDataOutput()
    private let lifecycle=NSLock();private var closed=false
    private var layer:AVCaptureVideoPreviewLayer?,recording=false,encoder:PMEncryptedEncoder?,sink:PMEncryptedScratch?,snapshot:String?,started=CMTime.invalid,last=CMTime.invalid,timer:DispatchWorkItem?,audioEnabled=false,videoWidth=0,videoHeight=0
    private let record=UIButton(type:.system),shoot=UIButton(type:.system),stop=UIButton(type:.system)
    init(authority:PMVaultAuthority,actor:PMVaultActor,kind:String,maxDuration:Double){self.authority=authority;self.actor=actor;self.kind=kind;self.maxDuration=maxDuration;super.init(nibName:nil,bundle:nil);modalPresentationStyle = .fullScreen}
    required init?(coder:NSCoder){fatalError("init(coder:) is unavailable")}
    override func viewDidLoad(){super.viewDidLoad();view.backgroundColor = .black;let cancel=UIButton(type:.system);cancel.setTitle("取消",for:.normal);cancel.addTarget(self,action:#selector(userCancel),for:.touchUpInside);shoot.setTitle("拍照",for:.normal);shoot.addTarget(self,action:#selector(takePhoto),for:.touchUpInside);record.setTitle("开始录像",for:.normal);record.addTarget(self,action:#selector(toggleRecording),for:.touchUpInside);stop.setTitle("完成录像",for:.normal);stop.addTarget(self,action:#selector(toggleRecording),for:.touchUpInside);stop.isHidden=true
        let stack=UIStackView(arrangedSubviews:[cancel,shoot,record,stop]);stack.axis = .horizontal;stack.distribution = .fillEqually;stack.translatesAutoresizingMaskIntoConstraints=false;view.addSubview(stack);NSLayoutConstraint.activate([stack.leadingAnchor.constraint(equalTo:view.safeAreaLayoutGuide.leadingAnchor),stack.trailingAnchor.constraint(equalTo:view.safeAreaLayoutGuide.trailingAnchor),stack.bottomAnchor.constraint(equalTo:view.safeAreaLayoutGuide.bottomAnchor,constant:-12),stack.heightAnchor.constraint(equalToConstant:56)]);shoot.isHidden=kind=="video";record.isHidden=kind=="photo";permissions()}
    override func viewDidLayoutSubviews(){super.viewDidLayoutSubviews();layer?.frame=view.bounds;view.subviews.forEach{view.bringSubviewToFront($0)}}
    private func valid()->Bool{lifecycle.lock();let active = !closed;lifecycle.unlock();return active&&authority?.check(actor)==true}
    private func permitted(_ type:AVMediaType,_ completion:@escaping(Bool)->Void){guard valid() else{return};let status=AVCaptureDevice.authorizationStatus(for:type);if status == .notDetermined{AVCaptureDevice.requestAccess(for:type){allowed in if self.valid(){completion(allowed)}}}else if valid(){completion(status == .authorized)}}
    private func permissions(){guard ["photo","video","both"].contains(kind) else{finish(.failure(PMProtectedError.invalidInput));return};permitted(.video){camera in guard camera else{self.finish(.failure(PMProtectedError.rejected));return};if self.kind=="photo"{self.configure(audio:false)}else{self.permitted(.audio){microphone in guard microphone else{self.finish(.failure(PMProtectedError.rejected));return};self.configure(audio:true)}}}}
    private func configure(audio:Bool){sessionQueue.async{do{guard self.valid(),let camera=AVCaptureDevice.default(.builtInWideAngleCamera,for:.video,position:.back) else{throw PMProtectedError.rejected};let input=try AVCaptureDeviceInput(device:camera);self.session.beginConfiguration();defer{self.session.commitConfiguration()};self.session.sessionPreset = .hd1280x720;guard self.session.canAddInput(input) else{throw PMProtectedError.storage};self.session.addInput(input)
            self.video.videoSettings=[kCVPixelBufferPixelFormatTypeKey as String:kCVPixelFormatType_420YpCbCr8BiPlanarVideoRange];self.video.alwaysDiscardsLateVideoFrames=true;self.video.setSampleBufferDelegate(self,queue:self.samples);guard self.session.canAddOutput(self.video),self.session.canAddOutput(self.photo) else{throw PMProtectedError.storage};self.session.addOutput(self.video);self.session.addOutput(self.photo)
            if audio{guard let microphone=AVCaptureDevice.default(for:.audio) else{throw PMProtectedError.storage};let audioInput=try AVCaptureDeviceInput(device:microphone);guard self.session.canAddInput(audioInput),self.session.canAddOutput(self.audio) else{throw PMProtectedError.storage};self.session.addInput(audioInput);self.audio.setSampleBufferDelegate(self,queue:self.samples);self.session.addOutput(self.audio);self.audioEnabled=true}
            if let connection=self.video.connection(with:.video),connection.isVideoOrientationSupported{connection.videoOrientation = .portrait};if let connection=self.photo.connection(with:.video),connection.isVideoOrientationSupported{connection.videoOrientation = .portrait}
            DispatchQueue.main.async{guard self.valid() else{return};let layer=AVCaptureVideoPreviewLayer(session:self.session);layer.videoGravity = .resizeAspectFill;layer.frame=self.view.bounds;self.view.layer.insertSublayer(layer,at:0);self.layer=layer}
            self.sessionQueue.async{
                // Linearize a queued start with finish(). A cancellation cannot
                // return and then allow this start through a prior stale check.
                self.lifecycle.lock();guard !self.closed,self.authority?.check(self.actor)==true else{self.lifecycle.unlock();return};self.session.startRunning();self.lifecycle.unlock();if !self.valid(){self.session.stopRunning()}
            }
        }catch{self.finish(.failure(error))}}}
    @objc private func userCancel(){cancel()}
    @objc private func takePhoto(){guard valid(),session.isRunning else{return};shoot.isEnabled=false;record.isEnabled=false;let settings=AVCapturePhotoSettings(format:[AVVideoCodecKey:AVVideoCodecType.jpeg]);photo.capturePhoto(with:settings,delegate:self)}
    func photoOutput(_ output:AVCapturePhotoOutput,didFinishProcessingPhoto photo:AVCapturePhoto,error:Error?){samples.async{do{guard error==nil,self.valid(),let authority=self.authority,var data=photo.fileDataRepresentation() else{throw PMProtectedError.rejected};defer{data.resetBytes(in:0..<data.count)};let sink=try PMEncryptedScratch(authority:authority,actor:self.actor,name:"camera-"+UUID().uuidString.lowercased()+".jpg");try sink.append(data);guard self.valid() else{throw PMProtectedError.cancelled};let path=try sink.stage(),info=try pmSourceInfo(self.actor,path);self.finish(.success(["path":path,"name":info["name"] ?? "photo.jpg","size":info["size"] ?? 0,"kind":"image","mimeType":"image/jpeg","width":photo.resolvedSettings.photoDimensions.width,"height":photo.resolvedSettings.photoDimensions.height,"duration":0]))}catch{self.finish(.failure(error))}}}
    @objc private func toggleRecording(){samples.async{guard self.valid() else{return};if self.recording{self.stopRecording()}else{self.recording=true;self.started = .invalid;self.last = .invalid;self.timer=DispatchWorkItem{[weak self] in self?.samples.async{self?.stopRecording()}};if let timer=self.timer{DispatchQueue.main.asyncAfter(deadline:.now()+self.maxDuration,execute:timer)};DispatchQueue.main.async{guard self.valid() else{return};self.record.isHidden=true;self.shoot.isHidden=true;self.stop.isHidden=false}}}}
    func captureOutput(_ output:AVCaptureOutput,didOutput sampleBuffer:CMSampleBuffer,from connection:AVCaptureConnection){guard recording,valid(),let authority=authority else{return};do{if output===video{guard let image=CMSampleBufferGetImageBuffer(sampleBuffer) else{throw PMProtectedError.storage};if encoder==nil{let sink=try PMEncryptedScratch(authority:authority,actor:actor,name:"camera-"+UUID().uuidString.lowercased()+".mp4");self.sink=sink;videoWidth=CVPixelBufferGetWidth(image);videoHeight=CVPixelBufferGetHeight(image);guard let encoder=PMEncryptedEncoder(width:Int32(videoWidth),height:Int32(videoHeight),audio:audioEnabled,bitrate:4_000_000,emit:{data in do{guard self.valid() else{throw PMProtectedError.rejected};try sink.append(data);return true}catch{return false}}) else{throw PMProtectedError.storage};self.encoder=encoder;started=CMSampleBufferGetPresentationTimeStamp(sampleBuffer)
                    let ci=CIImage(cvPixelBuffer:image);if let cg=CIContext(options:[.cacheIntermediates:false]).createCGImage(ci,from:ci.extent),var data=UIImage(cgImage:cg).jpegData(compressionQuality:0.8){defer{data.resetBytes(in:0..<data.count)};let thumbnail=try PMEncryptedScratch(authority:authority,actor:actor,name:"snapshot-"+UUID().uuidString.lowercased()+".jpg");try thumbnail.append(data);snapshot=try thumbnail.stage()}}
                last=CMSampleBufferGetPresentationTimeStamp(sampleBuffer);guard encoder?.appendVideo(image,time:last,duration:CMSampleBufferGetDuration(sampleBuffer))==true else{throw PMProtectedError.storage}
            }else if output===audio,let encoder=encoder{guard encoder.appendAudio(sampleBuffer) else{throw PMProtectedError.storage}}
        }catch{recording=false;encoder?.cancel();sink?.cancel();finish(.failure(error))}}
    private func stopRecording(){guard recording else{return};recording=false;timer?.cancel();do{guard let authority=authority,authority.check(actor),let encoder=encoder,let sink=sink,encoder.finish() else{throw PMProtectedError.rejected};let path=try sink.stage(),info=try pmSourceInfo(actor,path),elapsed=CMTimeGetSeconds(CMTimeSubtract(last,started));var value:[String:Any]=["path":path,"name":info["name"] ?? "video.mp4","size":info["size"] ?? 0,"kind":"video","mimeType":"video/mp4","duration":elapsed.isFinite ? max(0,elapsed):0,"width":videoWidth,"height":videoHeight];if let snapshot=snapshot{value["snapshotPath"]=snapshot};finish(.success(value))}catch{encoder?.cancel();sink?.cancel();finish(.failure(error))}}
    func cancel(){finish(.success(NSNull()))}
    private func finish(_ value:Result<Any,Error>){lifecycle.lock();guard !closed else{lifecycle.unlock();return};closed=true;lifecycle.unlock();samples.async{self.recording=false;self.timer?.cancel();self.encoder?.cancel();self.sink?.cancel();self.sessionQueue.async{self.session.stopRunning();self.video.setSampleBufferDelegate(nil,queue:nil);self.audio.setSampleBufferDelegate(nil,queue:nil);DispatchQueue.main.async{let callback=self.completion;self.completion=nil;self.layer?.session=nil;self.layer?.removeFromSuperlayer();self.dismiss(animated:true){callback?(value)}}}}}
    deinit{encoder?.cancel();sink?.cancel()}
}
